app.MapGet("/api/orders", async (
    int page = 1, int pageSize = 20, AppDbContext db, CancellationToken ct) =>
{
    page = Math.Max(1, page);
    pageSize = Math.Clamp(pageSize, 1, 100);

    var baseQuery = db.Orders.AsNoTracking().Where(o => o.Status == OrderStatus.Pending);

    // Expensive on large tables — consider skipping or caching
    var total = await baseQuery.CountAsync(ct);

    var items = await baseQuery
        .OrderByDescending(o => o.CreatedAt)
        .ThenBy(o => o.Id)
        .Skip((page - 1) * pageSize)
        .Take(pageSize)
        .Select(o => new OrderSummaryDto(o.Id, o.Total, o.CreatedAt))
        .ToListAsync(ct);

    return Results.Ok(new { page, pageSize, total, items });
});

app.MapGet("/api/orders/feed", async (
    string? cursor, int pageSize, AppDbContext db, CancellationToken ct) =>
{
    pageSize = Math.Clamp(pageSize is 0 ? 20 : pageSize, 1, 100);
    DateTime? cursorTime = null;
    Guid? cursorId = null;
    if (!string.IsNullOrEmpty(cursor))
        (cursorTime, cursorId) = DecodeCursor(cursor);

    var query = db.Orders.AsNoTracking().Where(o => o.Status == OrderStatus.Pending);

    if (cursorTime is not null && cursorId is not null)
        query = query.Where(o =>
            o.CreatedAt < cursorTime ||
            (o.CreatedAt == cursorTime && o.Id < cursorId));

    var items = await query
        .OrderByDescending(o => o.CreatedAt)
        .ThenByDescending(o => o.Id)
        .Take(pageSize + 1)
        .Select(o => new OrderSummaryDto(o.Id, o.Total, o.CreatedAt))
        .ToListAsync(ct);

    var hasMore = items.Count > pageSize;
    if (hasMore) items.RemoveAt(pageSize);
    var next = hasMore ? EncodeCursor(items[^1]) : null;
    return Results.Ok(new { items, nextCursor = next, hasMore });
});

